"""Verify the commit/resource/worker serialized hw_emu pipeline traces."""
from pathlib import Path
import argparse,json,hashlib,re,time
p=argparse.ArgumentParser();p.add_argument('run',type=Path);p.add_argument('build',type=Path);p.add_argument('--publish',action='store_true');a=p.parse_args();out=a.run;build=a.build
m=json.loads((out/'manifest.json').read_text());assert m['returncode']==0;r=json.loads((out/'result.json').read_text());assert r['status']=='passed'
expected=(12,5,12) if a.publish else (10,4,12);assert tuple(r[k] for k in ['commit_calls','resource_calls','worker_calls'])==expected and r['authority_reuploads']==0 and r['observations']==4 and r['path_costs']==[4,7]
assert r['stale_validation_rejected'] and r['fresh_validation_passed']
if a.publish:assert r['published_path_verified'] and r['owner_membership_query_verified']
log=(out/'run.log').read_text();commits=[tuple(map(int,x)) for x in re.findall(r'XRT net_commit call=(\d+) op=(\d+) status=(\d+).*total_authority_uploads=(\d+)',log)];ops=[1,2,2,2,3,3,6,5,6,6]+([3,7] if a.publish else []);assert commits==[(i+1,op,4 if i==8 else 0,0) for i,op in enumerate(ops)]
reads=[tuple(map(int,x)) for x in re.findall(r'XRT resource call=(\d+) node=(\d+) status=(\d+) occupancy=(\d+) history=(\d+) version=(\d+)',log)];expected_reads=[(1,10,1,0,0,0),(2,7,0,2,0,2),(3,10,1,0,0,0),(4,7,0,2,1,3)]+([(5,7,0,3,1,4)] if a.publish else []);assert reads==expected_reads
workers=[tuple(map(int,x)) for x in re.findall(r'XRT resource_worker call=(\d+) op=(\d+) queued=(\d+) observations=(\d+) status=(\d+) authority_uploads=(\d+)',log)];assert workers==[(i+1,op,q,n,0,0) for i,(op,q,n) in enumerate([(4,1,0),(2,0,0),(1,1,1),(2,0,1),(1,1,2),(2,0,2),(4,1,2),(2,0,2),(1,1,3),(2,0,3),(1,1,4),(2,0,4)])]
inputs=json.loads((out/'inputs.json').read_text());assert all(hashlib.sha256(Path(p).read_bytes()).hexdigest()==h for p,h in inputs.items());image_hash=hashlib.sha256((build/'joint.xclbin').read_bytes()).hexdigest();assert image_hash==m['xclbin_sha256']
assert 'All the simulator processes exited successfully' in (out/'stdout.log').read_text();paths=[out/'result.json',out/'run.log',out/'stdout.log',out/'inputs.json',out/'host'];report={'status':'passed','verified_ns':time.time_ns(),'actual_cu_calls':sum(expected),'published_path':a.publish,'xclbin_sha256':image_hash,'result':r,'evidence_hashes':{str(p):hashlib.sha256(p.read_bytes()).hexdigest() for p in paths},'scope':'Serialized shared-BO hw_emu fixture; deliberate negotiated overuse, not final legal full-design routing, autonomous async protocol or board proof','board_result':False,'research_complete':False};(out/'trace_audit.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps({'status':'passed','actual_cu_calls':sum(expected),'published_path':a.publish}))
